import{_ as r,a as t}from"./chunks/61a66cb3d7627f19887e.BfKHYAfm.js";import{_ as i,C as a,o,c as s,j as e,a as n,E as d,a6 as m}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"作为一个拖延者，这套深度工作策略让我在30天内赚了70万美元","description":"","frontmatter":{"title":"作为一个拖延者，这套深度工作策略让我在30天内赚了70万美元","originalTitle":"This Deep Work Strategy Made Me $700K In 30 Days (As A Procrastinator)","date":"2024-04-12","originalUrl":"https://thedankoe.com/letters/this-deep-work-strategy-made-me-700k-in-2-weeks-as-a-procrastinator/","minutes":16,"sourceHash":"8f9a603d26c2b4499f2df3669dba4bd69aa59935b3bb55b7e2d792b2cee14407","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/this-deep-work-strategy-made-me-700k-in-2-weeks-as-a-procrastinator/"}]]},"headers":[],"relativePath":"letters/this-deep-work-strategy-made-me-700k-in-2-weeks-as-a-procrastinator.md","filePath":"letters/this-deep-work-strategy-made-me-700k-in-2-weeks-as-a-procrastinator.md"}'),h={name:"letters/this-deep-work-strategy-made-me-700k-in-2-weeks-as-a-procrastinator.md"};function c(u,p,g,k,_,f){const l=a("ArticleMeta");return o(),s("div",null,[p[0]||(p[0]=e("h1",{id:"作为一个拖延者-这套深度工作策略让我在30天内赚了70万美元",tabindex:"-1"},[n("作为一个拖延者，这套深度工作策略让我在30天内赚了70万美元 "),e("a",{class:"header-anchor",href:"#作为一个拖延者-这套深度工作策略让我在30天内赚了70万美元","aria-label":'Permalink to "作为一个拖延者，这套深度工作策略让我在30天内赚了70万美元"'},"​")],-1)),d(l),p[1]||(p[1]=m('<p><a href="https://www.youtube.com/embed/y0oEpR1qJj4?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我拖延得……非常厉害。</p><p>但我发现这是一件好事。拖延症是我实现大多数人认为不可能之事的一项超能力。</p><p>我会一直等到最后一刻，但在那最后一刻，我会进入心流状态，我的大脑根本无法从手头的任务中分心。</p><p>当我这样做时，工作质量要比我在前几周做零散的“计划内”工作高得多。</p><p>我还有其他事情要操心，如果工作不是我脑子里的唯一一件事，工作质量就会下降。</p><p>我发现这是一种性格特征。</p><p>这就是某些人天生的运作方式。</p><p>你只有在需要专注的时候才会专注。</p><ul><li>你不擅长回复别人的信息。</li><li>你在学校里很少按时交作业。</li><li>客户的工作总是拖到最后一刻。</li><li>你很难在商业上取得进展（因为在需要发布项目时，没有人来管理监督你）。</li></ul><p>如果这就是你，那么拖延症就是你超越99%的人的关键……前提是你得学会驾驭这种力量。</p><p>你拖延的工作并不像电子游戏或体育运动那样是实时的，可以在努力后获得即时反馈。</p><p>社会让你为这种性格特征感到自责。你总是觉得自己落后于他人，因为你不能、也不应该和他们玩同样的游戏。</p><p>你不需要改变。你需要了解自己，据此构建你的生活，并做出经过深思熟虑的决定。</p><h2 id="战术性压力-——-强迫自己去生存" tabindex="-1">战术性压力 —— 强迫自己去生存 <a class="header-anchor" href="#战术性压力-——-强迫自己去生存" aria-label="Permalink to &quot;战术性压力 —— 强迫自己去生存&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>我做过的最好的决定，往往也是最愚蠢的。</p><p>19岁时，我刷爆了我的第一张信用卡来为一门生意囤货，结果那门生意很快就失败了。</p><p>我签了好几份公寓租约，而我原本以为自己根本负担不起。</p><p>因为看到了一个机会，我处理掉了自己所有的东西，飞越整个国家。</p><p>我买了一款昂贵的软件，清空了我的银行账户，以此作为对商业成功的押注。</p><p>我在产品做出来之前，就建了一个落地页并接受订单。我每次发布产品都是这么干的，因为，第一，如果卖不出去，我就不用浪费更多时间。第二，如果卖出去了，我就被迫要在发布日期之前把它做出来。</p><p>每次我冒这些险的时候，我都只给自己两个选择：</p><ol><li>想办法搞定</li><li>被彻底摧毁</li></ol><p>这是我大脑的一场季度举重比赛。我把自己置于心理卧推的极限重量之下，并强迫自己在没有保护员的情况下把它举起来。</p><p>我在商业领域经常看到的一个例子是：</p><p>“我应该购买这款软件，还是用免费版？”</p><p>“我应该买门课程，还是浪费时间自己摸索？”</p><p>“我应该现在开始，还是等到现状带来的痛苦大到无法忍受，导致我最终在两年后才开始？”</p><p>答案显而易见。</p><p>当我花了1000美元买软件时（当时那是我银行账户里最后的1000美元），我就被迫去学习并使用那款软件进行构建，好把这笔钱赚回来。</p><p>当我花了3500美元买一门课程时，我就被迫让学到的东西发挥作用，好把这笔钱赚回来。</p><p>当我搬进月租8000美元的公寓时，我就被迫增加收入来让这笔开销显得轻松，结果就是我的银行账户每月额外增加了10万美元。</p><p>当我靠着一个还没做出来的产品在30天内赚了70万美元时，我就被迫拿出了我这辈子最出色的工作状态去把它做出来。</p><p>为了严谨起见，也为了那些可能从中受益的人，2023年5月的实际数字是687,886美元。</p><p>发生了一些事情：</p><ul><li>我创建了一个为期2周的同期课程，围绕一个主题进行4次通话，售价150美元</li><li>像同期课程这样的东西自带稀缺性，因为有报名截止日期</li><li>我当时正在提高另一门课程的价格（制造更多稀缺性）</li><li>我有其他产品的常规销量</li><li>我使用了稍后会详细介绍的策略来推广它们</li><li>在我旅程的这个阶段，我已经拥有了相当庞大的受众，如果没有投入4年的努力，这是不可能实现的</li></ul><p>这些因素的混合，让我赚到了我单月见过的最多的钱。</p><p>（<strong>旁注：</strong>对于数字产品，你可以快速构建并频繁执行此操作。我只花了4-5个小时就完成了上述同期课程的材料制作。而对于实体产品，你要么得边卖边做，要么得在产品开发上投入大量时间，比如我发布我的书时就是这样。这就是为什么我会先用内容和数字产品来重点测试我的想法）。</p><p>你对现状安之若素，是因为你不愿承担那种能逼迫你达到你目前无法想象的高度的风险。</p><p>偶尔会流传着这样一个迷思：</p><p>金鱼会根据你放它们进去的鱼缸大小来生长。但如果你把它们养在一个小鱼缸里，它们就永远长不大。</p><p>实际上，小鱼缸会导致水质变差和自由游动的空间变小。所以，并不是它们永远长不大，而是它们会受尽折磨并死去。这是一个微小但极其重要的区别。</p><p>这与我战术性压力的概念非常相似：</p><p>有意识地决定将自己逼入非死即生的境地——你知道自己有能力把它搞定——让你别无选择，只能克服恐惧。其结果是一段高强度的时期，它将推动你进入人生的下一个阶段。</p><p>战术性压力的目的是让你自己冲向未知，进入无限潜力的领域。因为如果你不这么做，熵就会掌控一切，你开始慢慢沉沦并遭受煎熬，直到痛苦大到你不得不去这么做为止。</p><p>当你投身于能够改变生活的新环境中时，你会被海量的信息所淹没。</p><p>那超出了你大脑的消化能力。</p><p>因此，你被迫要在被混乱吞没或创造清晰之间做出选择。</p><p>你设定了一个近乎不可能的目标，做出了一个逼迫自己跳下悬崖的决定，并将随之而来的压力转化为强大的燃料，让你能够比任何人都更拼命工作。这在心理层面有几个作用：</p><ul><li><strong>保持全局观</strong> —— 当你处于非死即生的境地时，除了专注于目标，你别无选择。分心事物根本不会进入你的意识，所以你不可能被它们诱惑。</li><li><strong>创造截止日期</strong> —— 大多数截止日期不起作用，因为它们不是真的。如果你在某件事上花了钱，或者为某件事收了钱，你就会被迫交付。一个真正的截止日期就此诞生。</li><li><strong>收窄注意力</strong> —— 生存模式会让你陷入暂时的压力状态。压力会收窄你对当前任务的注意力，这让你得以生存。你脑子里唯一的一件事就是实现你定下的目标。</li><li><strong>让生活变得愉快</strong> —— 既然你的目标占据了大脑的最前沿，你经历的任何事情都会被过滤成对该目标有用的辅助。你读的书、进行的对话、消费的内容，似乎都“神奇地”帮到了你。随着模式识别被推向超速状态，多巴胺会充斥你的大脑。</li></ul><p>如果你的生活并不愉快，或者你没有取得进展，也许是时候纵身一跃了。</p><p>这并不适合所有人，但<em>到底</em>是什么在阻碍你开始新生活？辞掉工作？没有B计划？</p><p>只给自己两个选择：赢，或者死。如果你明白成功是技能和知识的结果，而不是靠运气，我相信你一定能想出办法来。</p><p>我不想听到任何借口，因为那完全就是缺乏技能的最典型例子。你无法控制你的自负，也无法用你的大脑去开创自己的道路。</p><h2 id="制造紧迫感-——-没人谈论的深度工作惯例" tabindex="-1">制造紧迫感 —— 没人谈论的深度工作惯例 <a class="header-anchor" href="#制造紧迫感-——-没人谈论的深度工作惯例" aria-label="Permalink to &quot;制造紧迫感 —— 没人谈论的深度工作惯例&quot;">​</a></h2><p>首先，除非你完全掌控自己的生活，否则这根本行不通。</p><p>你每天去上班的原因是，如果不去，你的生存就会受到威胁。如果你想获得自由，你就必须在自己的工作中重现这种效应。大多数人之所以放弃，是因为没有任何东西约束他们继续为了自己的愿景去写作、构建和销售。</p><p>每个人都有变富有的渴望，因为他们渴望做自己想做的工作。</p><p>然而，大多数人压抑了这种渴望，因为他们被条件反射地灌输了自己毫无机会的观念。又或者，他们只是对赚钱感到内疚，因为他们成长的环境——无论是物理环境还是数字环境——与金钱有着极其糟糕的关系。</p><p>我能做到这一点的唯一原因是，我完全掌控了我的时间和收入……因为我拥有一门生意。</p><p>其中一些策略可以在工作中帮到你，但你需要一门生意，才能充分撬动承担风险所带来的不对称回报。</p><p>生意为你提供了随心所欲增加收入的创造性边界。这在99.99%的工作中是不可能实现的，而且我猜你也不属于那极少数能在企业阶梯上摸爬滚打10到20年并赚到50万美元年薪的人。要知道，只要你集中精力在1-3年内构建自己的事业，就能实现这个目标。我的好几位朋友和学生就是因为信任我教授的受众积累和数字产品构建流程，在那个时间范围内赚到了这个数。</p><p>现在的问题是：</p><p><em>“当我承担那种逼迫我为了生存而战的风险时，我到底该怎么做？”</em></p><p>我将带你详细了解让我能在30天内赚到70万美元的确切季度计划。</p><p>你想重复多少次都可以。在最初的几个回合里，你赚不到大钱，但随着你技能组合的完善和你工作受众的增长，你会对自己能做到的事情感到惊讶。</p><h3 id="_0-我如何规划我的一天" tabindex="-1">0) 我如何规划我的一天 <a class="header-anchor" href="#_0-我如何规划我的一天" aria-label="Permalink to &quot;0) 我如何规划我的一天&quot;">​</a></h3><p>你以前可能读过关于我日常作息的文章。</p><ul><li>每天早上的第一个时间块，我用来构建新项目（目前是我下一本书）。</li><li>每天早上的第二个时间块，我用来写作。</li><li>每天早上的第三个时间块，我用来维护生意的各个方面。</li><li>在这些时间块之间，我会去散步以理清思路并为我的工作设定意图。</li><li>我去健身房的时间是我工作的严格截止时间。</li></ul><p>下班后我还有生活要去享受，所以我知道我必须在早上给自己分配的时间内完成工作。</p><p>这似乎违反直觉，但我的健康和生活确实优先于工作，而这反而让我的工作更具影响力。</p><p>我必须在固定时间去健身房，这样我下午才能自由支配，因此我的工作自然而然地非常专注。</p><h3 id="_1-季度项目" tabindex="-1">1) 季度项目 <a class="header-anchor" href="#_1-季度项目" aria-label="Permalink to &quot;1) 季度项目&quot;">​</a></h3><p>如果你不推销自己的产品，你就会被迫去推销别人的产品。</p><p>在网络空间里有一种思维病毒：</p><p><em>“现在好像每个人都在卖东西。”</em></p><p><em>“看看这家伙在卖产品，他是个见钱眼开的叛徒。”</em>（我在很多高水平大佬的帖子下面都看到过这种评论）。</p><p><em>“广告，广告，广告，全是广告。”</em>（前几天我在阿里·阿卜杜勒（Ali Abdaal）的推广视频里看到过）。</p><p>是的，傻瓜，你需要一个产品来赚取收入。根本就没有其他办法。这就是经济运转的方式。买卖交易。当然，你可以去投资，但你的本金是哪来的？还不是通过在一家销售产品的公司里扮演机械的角色，付出你那可被替代的努力来换取工资。而且如果你赚不到很多钱，那祝你好运能靠投资赚到什么大钱吧。</p><p>别管那些盲目的伪君子，无论如何都要发布一款产品。</p><p>自从我开始创业以来，我每个季度都会发布一个新项目。为什么？</p><ul><li><strong>这给了我大量与产品相关的写作灵感（因为我正在充实大纲）。</strong>在发布之前，我把产品的大部分内容写成了推文和时事通讯，以测试哪些想法和营销角度行之有效。</li><li><strong>产品<em>发布</em>是你的产品生命周期中最赚钱的部分。</strong> 就像一张图表，它迅速飙升，然后猛烈下跌，最后在一个特定的数字上趋于平稳。</li><li><strong>我想让我的收入来源多样化。</strong> 当你建立受众时，一款产品可能会卖得很好，但你绝不会把发财的希望全都押在一只股票上。</li><li><strong>我变得更有经验，并且每个季度都有更有价值的东西可以发布。</strong> 如果你把做生意这套流程走对了，你应该推出一些比竞争对手更新、更好的东西。这会导致很多人抄袭你，试图利用你的好点子赚钱，但你仍然能获得绝大部分的销售额和声誉。按季度的发布让你始终处于领先地位。</li><li><strong>我没必要去操心某一次发布是否能取得巨大的成功，</strong> 因为我知道3个月内我就会对它进行迭代。</li><li><strong>它给了我必须达成的季度公开截止日期。</strong> 我不需要去猜测下一个项目什么时候发布（因此我的业务就不会停滞不前）。如果我想让收入增加——而不是减少——我就必须发布产品才能生存。</li></ul><p>人们经常问：“在这个领域，到底是什么事情让你能远远领先于其他人？”</p><p>我会自信地说，那就是每个季度发布一个项目。</p><p>它建立起了我的权威，让我保持专注，并防止我试图去为一个死掉的产品输血。</p><p>在如此短的时间范围内，你能发布什么样的产品？</p><ul><li>课程</li><li>同期群课程（Cohorts）</li><li>辅导</li><li>电子书</li><li>模板</li></ul><p>你可以快速构建并测试这些产品。如果一个失败了，没关系，再建一个。如果奏效了，太棒了，开始构建配套的补充产品，并考虑将那个想法变成一门需要更多资金或资源的生意。举个例子，正是《两小时写手》（2 Hour Writer）的成功催生了打造 Kortex 的想法。这个想法已经通过销售和互动得到了验证，因为促成该想法的产品和内容已经被验证过了。</p><p>在起步阶段，这些应该构成你品牌的基础并建立现金流。在你拥有足够的资源之前，不要试图把你创造的产品搞得太复杂。</p><p>然后，你可以计划在其中一个季度发布档期推出更大的产品（比如软件），但仍然要继续发布其他东西。</p><p>现在，你不需要发布一个全新的产品。你可以：</p><ul><li>将产品组合成一个大礼包然后发布。</li><li>为当前产品添加一个新模块并提高价格——你可以在特定日期“发布”这种涨价促销。</li><li>每个季度一遍又一遍地运行同一个同期群课程。这可能是最简单的做法。我建议为每个同期群设置不同的主题，这样你就能吸引有不同需求的客户。</li></ul><p>通过每个季度这样做，我就可以根据发布带来的收入来衡量我品牌的影响力和权威性。</p><p>当我在粉丝数大约500人时发布一款自由职业产品，我赚了大概3,000美元。当我在推特粉丝数达到10,000人时发布一款品牌塑造产品，我赚了大概10,000美元。3年后，当我发布一个写作同期群课程时，我赚了70万美元。那些只卖一款产品（而且不去改进它）的人，最终会因为用力过度地去营销而破坏了他们在受众中的信任感，同时赚到的收入却<em>少得多</em>。</p><p>产品发布有很多细微之处。我们会在 <a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a> 的 Builder（构建者）层级中指导你掌握所有这些细节。</p><p><strong>经验教训</strong></p><p>你的深度工作（deep work）时段是由你的季度产品发布来驱动的。</p><ul><li>在开始阶段拥抱拖延。在发布之前，你还有时间。</li><li>在发布前的1-2个月内，专注于产品大纲和计划。</li><li>设定一个公开的发布日期。设定一个在那之前的3-4周的首次推广日期。先建立好销售页面来接受订单。执行发布并把产品做出来。</li></ul><p>如果你读过上一篇关于 <a href="/letters/disappear-and-come-back-unrecognizable-12-rules-to-change-your-life">创造的12条法则（The 12 Rules Of Creation）</a> 的信，你就会明白这些项目对于构建你的生活和工作至关重要。它们是唯一能朝着你的愿景和目标取得实质性进展的东西。如果你不在构建，你就是在走向灭亡。</p><h3 id="_2-公开写作" tabindex="-1">2) 公开写作 <a class="header-anchor" href="#_2-公开写作" aria-label="Permalink to &quot;2) 公开写作&quot;">​</a></h3><p>在线上业务中，你需要三样东西：</p><ol><li>欣赏你作品的受众。</li><li>为这些受众提供的一款有价值的产品。</li><li>能吸引人们成为你的受众并购买产品的有力论点。</li></ol><p>写作是这三者的基础。</p><p>我想再次强调这一点：</p><p><em>为这些受众提供的一款有价值的产品。</em></p><p>如果你拥有一家企业，这篇时事通讯丝毫不会惹恼你，因为你是以开明的视角来阅读它的。</p><p>如果你没有企业，你可能会误解它，或者只从片面的角度去阅读，尤其是如果你对金钱抱有负面态度的话。你必须跳出局限，意识到人们购买产品是因为他们需要这些产品，并且这些产品对他们的生活有益。这绝不仅仅是为了尽可能多地赚钱。它是为了解决别人生活中的一个问题，而这个解决之道的<em>价值远大于</em>你的要价。</p><p>并且，我也想请你跳出局限，想一想你买的所有那些对你生活毫无益处的无用产品，问问自己为什么不把这种心态应用到其他领域。人们花100美元买酒喝连眼睛都不眨一下（结果还损害了他们的健康），却不愿花100美元来提升自己的技能（这能提高他们的赚钱能力并从而改善生活质量）。</p><p>在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> （逮到你了）中，我教授了三点内容生态系统：</p><ul><li>写推文来测试想法。</li><li>写长推文（threads）来扩展这些想法。</li><li>将其中任何一个变成时事通讯，以培养你的受众并推广你的产品。</li><li>利用你的时事通讯来写新的推文和长推文，这样你的内容灵感就永不枯竭。</li></ul><p>我的朋友 Nick Verge 前几天问起了这个流程。这里有一张截图，希望能帮你从宏观角度看清它。</p><p><img src="'+t+'" alt=""></p><p>写作是这个策略的必要基础。我不能确切地告诉你该怎么做，因为我不了解你的情况，但我可以告诉你我是怎么做的。</p><p>如果你现在手头没有太多时间，你将无法做到所有这些，没关系。在你的前几次足以替代你工资收入的产品发布中，你并不需要做全套。</p><ul><li><strong>我每天早上写作60-90分钟。</strong> 我从我的时事通讯开始写，然后随着灵感浮现去写社交媒体帖子。</li><li><strong>我每天推广一次我的时事通讯。</strong> 我不会发布注册引导页去求着人们订阅。我直接发布实际的时事通讯（作为博客文章），这样人们就可以阅读它、获得价值、订阅它，并看到我在时事通讯中推广的产品。这就是我在非产品发布期间获得时事通讯订阅者并销售我的产品的方式。</li><li><strong>在产品发布那个月，我会集中我的内容主题。</strong> 在发布前的2个月里，我会随心所欲地写任何我想写的东西，然后在剩下的那一个月里，我只写与我要发布的产品相关的主题。（这正是我获得最多粉丝和建立最多权威的时候……当我在输出价值并发布一款展示我专业知识的产品时。）</li><li>我在此过程中逐步构思大纲并打造产品，但在公开截止日期之前，我会被迫去真正完成它。</li></ul><p>我是如何保持写作连贯性的？</p><p>因为我明白，如果我不写，我的受众就不会增长，我也就无法生存。我让自己一直处于一种持续的良好压力状态下，这种压力在早上唤醒我，让我开始写作。</p><p>如果我的受众不增长，我的产品发布就不会顺利，那我就离被迫去打工更近了一步。此外，随着你不断构建项目，你押注的东西也越多。如果我现在停止写作，整个 Kortex 就会死掉。我需要钱来建设它。而且我绝不会让它死掉。</p><p>一旦它稳定下来，我就可以休息一下，但我会去开启一个新项目，这样我的生活才能保持意义，而不会变得机械/无聊。</p><p>请注意，在这件事里，写作并不是唯一要做的事。你必须懂得如何在社交媒体上增长。你不能只是把内容随便往风里一撒，然后祈祷它能火。我<a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">之前谈到过这个</a>，并且会在下周的信里继续聊这个话题。</p><h3 id="_3-战术性推广" tabindex="-1">3) 战术性推广 <a class="header-anchor" href="#_3-战术性推广" aria-label="Permalink to &quot;3) 战术性推广&quot;">​</a></h3><p>到目前为止，我们的深度工作日常安排的结构如下：</p><ul><li><strong>一个能够朝着我们的愿景和目标取得实质性进展的公开季度项目。</strong> 这会创造一个真正的截止日期，但前提是<em>只有</em>当你在商业框架下为你所创造的价值收费时。</li><li><strong>每日写作，通过建立分层级的受众来推动项目的成功。</strong> 我写推文和长推文来吸引受众，将他们引流到我的时事通讯中，并在我提供了足够多的价值之后推广我的产品。</li></ul><p>那么，我并不是很喜欢在社交媒体上进行繁重的营销和销售。</p><p>我喜欢战术性的推广。</p><ul><li>我只在发布的最后一周才在社交媒体上推广我的产品。这样一来，除了每年那4个星期之外，我的主页都不会出现销售内容。人们喜欢这样，还经常夸我不“咄咄逼人或市侩推销”。</li><li>就像你在上面看到的那样，我会在每一封时事通讯中进行软推广。这就是我在发布期之外为我之前打造的产品造势的方法。我认为人们已经厌倦了每天在电子邮件里看到强买强卖，他们想要的是大量的价值，并拥有是否购买某物的<em>选择权</em>。他们不想有被强迫的感觉。</li><li>在产品发布之前，我每周的推广力度会越来越大。我的大部分收入都是在发布前的1-2天内赚到的，因为那是稀缺性开始发挥作用的时候。</li></ul><p>这就是我的全部策略。</p><p>这就是督促我每天早上工作和写作的动力。</p><p>这就是我如何从5年前从事网页设计工作以来，将我的收入翻了80倍（是的，没写错）。</p><p>如果你确确实实地为迭代和坚持做了<em>计划</em>，并强迫自己用正确的策略去完成工作，那么失败就是一个伪命题。</p><p>感谢你的阅读。周末愉快。</p><p>Dan</p><hr><p><a href="/en/letters/this-deep-work-strategy-made-me-700k-in-2-weeks-as-a-procrastinator">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',135))])}const x=i(h,[["render",c]]);export{y as __pageData,x as default};
